const resolveNotificationRequest = `-- name: ResolveNotificationRequest :many
UPDATE notifications SET resolved_at = CAST(?1 AS INTEGER)
WHERE thread_id = CAST(?2 AS TEXT) AND request_id = CAST(?3 AS TEXT) AND resolved_at IS NULL
RETURNING id
`

type ResolveNotificationRequestParams struct {
	Now       int64  `json:"now"`
	ThreadID  string `json:"threadId"`
	RequestID string `json:"requestId"`
}

func (q *Queries) ResolveNotificationRequest(ctx context.Context, arg ResolveNotificationRequestParams) ([]string, error) {
	rows, err := q.db.QueryContext(ctx, resolveNotificationRequest, arg.Now, arg.ThreadID, arg.RequestID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

