const upsertPushSubscription = `-- name: UpsertPushSubscription :one
INSERT INTO push_subscriptions (id, kind, endpoint, p256dh, auth, web_session_hash, device_id, user_agent, created_at)
VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, ?9)
ON CONFLICT (endpoint) DO UPDATE SET
    p256dh           = excluded.p256dh,
    auth             = excluded.auth,
    web_session_hash = excluded.web_session_hash,
    device_id        = excluded.device_id,
    user_agent       = excluded.user_agent,
    last_error       = NULL
RETURNING id, kind, endpoint, p256dh, auth, web_session_hash, device_id, user_agent, created_at, last_success_at, last_error
`

type UpsertPushSubscriptionParams struct {
	ID             string  `json:"id"`
	Kind           string  `json:"kind"`
	Endpoint       string  `json:"endpoint"`
	P256dh         string  `json:"p256dh"`
	Auth           string  `json:"auth"`
	WebSessionHash *string `json:"webSessionHash"`
	DeviceID       *string `json:"deviceId"`
	UserAgent      string  `json:"userAgent"`
	CreatedAt      int64   `json:"createdAt"`
}

// Upsert by endpoint: an existing row keeps its id and created_at, takes the new keys and owner, clears last_error.
func (q *Queries) UpsertPushSubscription(ctx context.Context, arg UpsertPushSubscriptionParams) (PushSubscription, error) {
	row := q.db.QueryRowContext(ctx, upsertPushSubscription,
		arg.ID,
		arg.Kind,
		arg.Endpoint,
		arg.P256dh,
		arg.Auth,
		arg.WebSessionHash,
		arg.DeviceID,
		arg.UserAgent,
		arg.CreatedAt,
	)
	var i PushSubscription
	err := row.Scan(
		&i.ID,
		&i.Kind,
		&i.Endpoint,
		&i.P256dh,
		&i.Auth,
		&i.WebSessionHash,
		&i.DeviceID,
		&i.UserAgent,
		&i.CreatedAt,
		&i.LastSuccessAt,
		&i.LastError,
	)
	return i, err
}
